import java.lang.instrument.Instrumentation;

/** Measurement agent only; does not transform any class. */
public final class SizeAgent {
    private static volatile Instrumentation instrumentation;

    private SizeAgent() { }

    public static void premain(String arguments, Instrumentation actual) {
        instrumentation = actual;
    }

    public static long sizeOf(Object object) {
        Instrumentation actual = instrumentation;
        if (actual == null) throw new IllegalStateException("Genuine Instrumentation agent was not loaded");
        return actual.getObjectSize(object);
    }
}

