import com.m3.collections.M3IndexMaskCompactor;
import com.m3.collections.M3LongArrayList;
import com.m3.collections.M3LongBitmapFilteredSnapshot;
import com.m3.collections.M3LongBitmapFilteredSnapshot.VersionedView;
import com.sun.management.ThreadMXBean;
import java.lang.management.ManagementFactory;
import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.Comparator;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.LongPredicate;
import java.util.function.LongSupplier;
import javax.management.ObjectName;

/** Bounded observations of actual product objects, not an implementation or a speed assertion. */
public final class VersionedViewResourceProbe {
    private static volatile Object retained;
    private static volatile long consumed;
    private static final ThreadMXBean THREADS =
            (ThreadMXBean) ManagementFactory.getThreadMXBean();

    private VersionedViewResourceProbe() { }

    private static Map<String, Object> measure(String name, int operations, Runnable operation) {
        long thread = Thread.currentThread().threadId();
        long allocatedBefore = THREADS.getThreadAllocatedBytes(thread);
        long cpuBefore = THREADS.getCurrentThreadCpuTime();
        long wallBefore = System.nanoTime();
        operation.run();
        long wall = System.nanoTime() - wallBefore;
        long cpu = THREADS.getCurrentThreadCpuTime() - cpuBefore;
        long allocated = THREADS.getThreadAllocatedBytes(thread) - allocatedBefore;
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("name", name);
        result.put("operations", operations);
        result.put("thread_allocated_bytes", allocated);
        result.put("thread_cpu_nanoseconds", cpu);
        result.put("wall_nanoseconds", wall);
        return result;
    }

    private static List<String> fields(Class<?> type) {
        List<Field> values = new ArrayList<>(List.of(type.getDeclaredFields()));
        values.sort(Comparator.comparing(Field::getName));
        List<String> result = new ArrayList<>();
        for (Field field : values) {
            if (!Modifier.isStatic(field.getModifiers())) {
                result.add(Modifier.toString(field.getModifiers()) + " "
                        + field.getType().getTypeName() + " " + field.getName());
            }
        }
        return result;
    }

    private static Map<String, Object> snapshotGraph(Object cache) throws IllegalAccessException {
        IdentityHashMap<Object, Boolean> seen = new IdentityHashMap<>();
        ArrayDeque<Object> pending = new ArrayDeque<>();
        pending.add(cache);
        long bytes = 0;
        Map<String, Integer> types = new java.util.TreeMap<>();
        while (!pending.isEmpty()) {
            Object value = pending.removeFirst();
            if (value instanceof Enum<?>) continue; // Shared enum constants are not owned storage.
            if (seen.put(value, Boolean.TRUE) != null) continue;
            bytes += SizeAgent.sizeOf(value);
            Class<?> type = value.getClass();
            types.merge(type.getTypeName(), 1, Integer::sum);
            if (type.isArray()) {
                if (!type.getComponentType().isPrimitive()) {
                    for (int i = 0; i < Array.getLength(value); i++) {
                        Object child = Array.get(value, i);
                        if (child != null) pending.add(child);
                    }
                }
            } else {
                if (!type.getName().startsWith("com.m3.collections.") && !(value instanceof BitSet)) {
                    throw new IllegalStateException("Unexpected snapshot graph owner: " + type.getName());
                }
                for (Class<?> owner = type; owner != Object.class; owner = owner.getSuperclass()) {
                    for (Field field : owner.getDeclaredFields()) {
                        if (Modifier.isStatic(field.getModifiers()) || field.getType().isPrimitive()) continue;
                        if (!field.trySetAccessible()) throw new IllegalStateException("Inaccessible field: " + field);
                        Object child = field.get(value);
                        if (child != null) pending.add(child);
                    }
                }
            }
        }
        return Map.of("objects", seen.size(), "bytes", bytes, "types", types);
    }

    private static String json(Object value) {
        if (value == null) return "null";
        if (value instanceof Number || value instanceof Boolean) return value.toString();
        if (value instanceof Map<?, ?> map) {
            List<String> parts = new ArrayList<>();
            for (Map.Entry<?, ?> entry : map.entrySet()) parts.add(json(entry.getKey().toString()) + ":" + json(entry.getValue()));
            return "{" + String.join(",", parts) + "}";
        }
        if (value instanceof Iterable<?> items) {
            List<String> parts = new ArrayList<>();
            for (Object item : items) parts.add(json(item));
            return "[" + String.join(",", parts) + "]";
        }
        return "\"" + value.toString().replace("\\", "\\\\").replace("\"", "\\\"")
                .replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t") + "\"";
    }

    public static void main(String[] arguments) throws Exception {
        if (arguments.length != 2) throw new IllegalArgumentException("variant and NMT output path are required");
        if (!THREADS.isThreadAllocatedMemorySupported() || !THREADS.isCurrentThreadCpuTimeSupported()) {
            throw new IllegalStateException("Required real VM counters are unavailable");
        }
        THREADS.setThreadAllocatedMemoryEnabled(true);
        THREADS.setThreadCpuTimeEnabled(true);
        long[] values = new long[1_024];
        for (int i = 0; i < values.length; i++) values[i] = i;
        M3LongArrayList source = M3LongArrayList.copyOf(values);
        long[] calls = {0};
        LongPredicate predicate = value -> { calls[0]++; return (value & 1L) == 0L; };
        LongSupplier revision = () -> 7L;
        VersionedView view = new VersionedView(source, predicate, revision);
        if (view.size() != 512 || calls[0] != 1_024) throw new AssertionError("Initial cache observations differ");
        Field cacheField = VersionedView.class.getDeclaredField("cache");
        if (!cacheField.trySetAccessible()) throw new IllegalStateException("Actual cache field is inaccessible");
        Object cache = cacheField.get(view);
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("variant", arguments[0]);
        result.put("runtime", System.getProperty("java.runtime.version"));
        result.put("vm", System.getProperty("java.vm.name"));
        result.put("source_values", values.length);
        result.put("selected_values", view.size());
        result.put("view_shallow_bytes", SizeAgent.sizeOf(view));
        result.put("cache_shallow_bytes", SizeAgent.sizeOf(cache));
        result.put("view_fields", fields(VersionedView.class));
        result.put("cache_fields", fields(cache.getClass()));
        result.put("cache_snapshot_graph", snapshotGraph(cache));
        result.put("graph_scope", "Cache and reachable owned snapshot objects only; excludes the view, shared source, callbacks, shared enum constants, VM metadata and native memory");
        List<Map<String, Object>> observations = new ArrayList<>();

        // Retain every new view so escape analysis cannot remove its object allocation.
        VersionedView[] views = new VersionedView[4_096];
        retained = views;
        for (int i = 0; i < 10_000; i++) retained = new VersionedView(source, predicate, revision);
        observations.add(measure("construct_retained_views", views.length, () -> {
            for (int i = 0; i < views.length; i++) views[i] = new VersionedView(source, predicate, revision);
            retained = views;
        }));
        for (int i = 0; i < 200_000; i++) consumed += view.size();
        long callsBefore = calls[0];
        for (int round = 0; round < 3; round++) {
            observations.add(measure("cached_size_round_" + round, 2_000_000, () -> {
                long sum = 0;
                for (int i = 0; i < 2_000_000; i++) sum += view.size();
                consumed = sum;
            }));
        }
        if (calls[0] != callsBefore) throw new AssertionError("Warm reads evaluated the predicate");
        result.put("warm_predicate_calls", calls[0] - callsBefore);
        for (int i = 0; i < 200; i++) { view.invalidate(); consumed = view.size(); }
        callsBefore = calls[0];
        observations.add(measure("invalidate_and_rebuild", 1_000, () -> {
            for (int i = 0; i < 1_000; i++) { view.invalidate(); consumed = view.size(); }
        }));
        long rebuildCalls = calls[0] - callsBefore;
        if (rebuildCalls != 1_024_000) throw new AssertionError("Rebuild callback count differs");
        result.put("measured_rebuild_predicate_calls", rebuildCalls);

        boolean nativeAvailable = M3IndexMaskCompactor.nativeAvailable();
        if (!nativeAvailable) throw new IllegalStateException("The genuine native library is required for this observation");
        LongPredicate nativePredicate = value -> (value & 1L) == 0L;
        for (int i = 0; i < 200; i++) retained = M3LongBitmapFilteredSnapshot.snapshot(
                values, nativePredicate, M3IndexMaskCompactor.Backend.NATIVE_REQUIRED);
        observations.add(measure("unchanged_native_snapshot", 1_000, () -> {
            for (int i = 0; i < 1_000; i++) retained = M3LongBitmapFilteredSnapshot.snapshot(
                    values, nativePredicate, M3IndexMaskCompactor.Backend.NATIVE_REQUIRED);
        }));
        result.put("native_available", nativeAvailable);
        result.put("observations", observations);
        result.put("heap_used_bytes_at_observation_end", ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed());
        result.put("process_memory_status", Files.readAllLines(Path.of("/proc/self/status")).stream()
                .filter(line -> line.startsWith("VmRSS:") || line.startsWith("VmSize:") || line.startsWith("VmHWM:")).toList());
        String nativeSummary = (String) ManagementFactory.getPlatformMBeanServer().invoke(
                new ObjectName("com.sun.management:type=DiagnosticCommand"), "vmNativeMemory",
                new Object[] {new String[] {"summary", "scale=KB"}}, new String[] {"[Ljava.lang.String;"});
        if (nativeSummary.contains("Native memory tracking is not enabled")) throw new IllegalStateException(nativeSummary);
        Files.writeString(Path.of(arguments[1]), nativeSummary);
        result.put("scope", "One bounded process per implementation with identical VM flags and input sizes; no universal speedup or installed-image claim");
        System.out.println(json(result));
    }
}

