    private static String sha(String text) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                .digest(text.getBytes(StandardCharsets.UTF_8)));
    }

    private static String resource(String name) throws Exception {
        try (var stream = M3CollectionViewInvalidationRecipeTest.class.getResourceAsStream(
                "/com/synexia/rewrite/hash-pinned-java/" + ID + "/" + name)) {
            return new String(Objects.requireNonNull(stream, name).readAllBytes(), StandardCharsets.UTF_8);
        }
    }

    private static Map<String, String> before() throws Exception {
        Map<String, String> files = new TreeMap<>();
        for (var entry : BEFORE.entrySet()) {
            String text = Files.readString(CRATE.resolve("preimages").resolve(entry.getKey()));
            assertEquals(entry.getValue(), sha(text));
            files.put(entry.getKey(), text);
        }
        return files;
    }

    private static Map<String, String> expected() throws Exception {
        Map<String, String> files = new TreeMap<>();
        for (var entry : AFTER.entrySet()) {
            String text = resource(entry.getKey().replace("/", "__") + ".txt");
            assertEquals(entry.getValue(), sha(text), "frozen candidate resource " + entry.getKey());
            files.put(entry.getKey(), text);
        }
        return files;
    }

    private static List<SourceFile> parse(Map<String, String> files) {
        List<SourceFile> result = JavaParser.fromJavaVersion().classpath(classpath()).build().parseInputs(
                files.entrySet().stream().map(entry -> Parser.Input.fromString(
                        Path.of(entry.getKey()), entry.getValue())).toList(), null, context()).toList();
        assertEquals(files.size(), result.size());
        for (SourceFile source : result) {
            assertInstanceOf(J.CompilationUnit.class, source);
            assertEquals(files.get(source.getSourcePath().toString()), source.printAll());
        }
        return result;
    }

    private static Recipe namedRecipe() throws Exception {
        try (var stream = M3CollectionViewInvalidationRecipeTest.class.getResourceAsStream(
                "/META-INF/rewrite/" + ID + ".yml")) {
            var loader = new YamlResourceLoader(Objects.requireNonNull(stream),
                    URI.create("classpath:/" + ID + ".yml"), new Properties());
            Recipe recipe = Environment.builder().load(loader).build().activateRecipes(NAME);
            assertTrue(recipe.validate().isValid());
            return recipe;
        }
    }

    private static List<Result> results(List<SourceFile> inputs) throws Exception {
        return namedRecipe().run(new InMemoryLargeSourceSet(inputs), context(), 1)
                .getChangeset().getAllResults();
    }

    private static Map<String, String> output(List<SourceFile> inputs) throws Exception {
        Map<String, String> output = new TreeMap<>();
        for (Result result : results(inputs)) {
            SourceFile after = Objects.requireNonNull(result.getAfter());
            assertInstanceOf(J.CompilationUnit.class, after);
            assertNull(output.put(after.getSourcePath().toString(), after.printAll()));
        }
        return output;
    }

    private static void assertExpected(Map<String, String> output) throws Exception {
        assertEquals(2, output.size(), "the named recipe must emit both reviewed corrections");
        assertEquals(AFTER.keySet(), output.keySet());
        for (var entry : output.entrySet()) assertEquals(AFTER.get(entry.getKey()), sha(entry.getValue()));
    }

    private static void refuse(List<SourceFile> inputs, String diagnostic) throws Exception {
        var leaf = new M3HashPinnedJavaSnapshotRecipe(ID);
        var inventory = leaf.getInitialValue(context());
        for (SourceFile input : inputs) leaf.getScanner(inventory).visit(input, context());
        var failure = assertThrows(IllegalStateException.class, () -> leaf.generate(inventory, context()));
        assertTrue(failure.getMessage().contains(diagnostic), failure.getMessage());

        var errors = new ArrayList<Throwable>();
        var ctx = new InMemoryExecutionContext(errors::add);
        ctx.putMessage("com.synexia.rewrite.hashPinnedJavaSnapshotRecipe.parserClasspath", classpath());
        List<Result> changed = List.of();
        try {
            changed = namedRecipe().run(new InMemoryLargeSourceSet(inputs), ctx, 1)
                    .getChangeset().getAllResults();
        } catch (RuntimeException error) {
            errors.add(error);
        }
        assertTrue(changed.isEmpty(), "SDK refusal must not publish candidate source");
        assertTrue(errors.stream().anyMatch(error -> causes(error).contains(diagnostic)),
                "SDK must expose the same refusal: " + diagnostic);
    }

    private static String causes(Throwable error) {
        StringBuilder text = new StringBuilder();
        for (Throwable current = error; current != null; current = current.getCause())
            text.append(current.getClass().getName()).append(": ").append(current.getMessage()).append('\n');
        return text.toString();
    }

    @Test void namedCompositionEmitsExactlyTwoReviewedJavaResults() throws Exception {
        var output = output(parse(before()));
        assertExpected(output);
        assertEquals(expected(), output);
        Path receiver = CRATE.resolve("target/receiver");
        if (Files.exists(receiver)) try (var paths = Files.walk(receiver)) {
            for (Path file : paths.filter(Files::isRegularFile).toList())
                assertTrue(AFTER.containsKey(receiver.relativize(file).toString()), "unowned receiver " + file);
        }
        for (var entry : output.entrySet()) {
            Path target = receiver.resolve(entry.getKey());
            Files.createDirectories(target.getParent());
            Files.writeString(target, entry.getValue(), StandardCharsets.UTF_8);
            assertEquals(AFTER.get(entry.getKey()), sha(Files.readString(target)));
        }
        Files.writeString(CRATE.resolve("target/actual-output.tsv"),
                "path\tsha256\n" + MAIN + "\t" + AFTER.get(MAIN) + "\n" + TEST + "\t" + AFTER.get(TEST) + "\n");
    }

    @Test void allFourMixedStatesConvergeAndFullPostimageIsFixedPoint() throws Exception {
        var baseline = before();
        var expected = expected();
        var paths = new ArrayList<>(expected.keySet());
        for (int mask = 0; mask < 4; mask++) {
            var mixed = new TreeMap<>(baseline);
            for (int i = 0; i < 2; i++) if ((mask & (1 << i)) != 0)
                mixed.put(paths.get(i), expected.get(paths.get(i)));
            var changes = output(parse(mixed));
            assertEquals(2 - Integer.bitCount(mask), changes.size(), "already satisfied state " + mask);
            mixed.putAll(changes);
            assertEquals(expected, mixed);
            assertTrue(output(parse(mixed)).isEmpty(), "complete no-change replay " + mask);
        }
    }

    @Test void serialPermutationAndIndependentParallelReplaysMatch() throws Exception {
        var baseline = before();
        var expected = expected();
        assertEquals(expected, output(parse(baseline)));
        var reversed = new ArrayList<>(parse(baseline));
        Collections.reverse(reversed);
        assertEquals(expected, output(reversed));
        assertEquals(expected, output(parse(baseline)));
        try (var workers = Executors.newFixedThreadPool(2)) {
            var first = workers.submit(() -> output(parse(baseline)));
            var second = workers.submit(() -> output(parse(baseline)));
            assertEquals(expected, first.get());
            assertEquals(expected, second.get());
        }
    }

    @Test void missingAndCodeShapedDriftRefuseBeforeAnyCandidate() throws Exception {
        var baseline = before();
        for (String path : baseline.keySet()) {
            var missing = new TreeMap<>(baseline);
            missing.remove(path);
            refuse(parse(missing), "required source missing: " + path);
            for (String decoy : List.of("\n// class Decoy { void invalidate() { cache = null; } }\n",
                    "\n/* String code = \"invalidationGeneration++;\"; */\n")) {
                var drift = new TreeMap<>(baseline);
                drift.put(path, baseline.get(path) + decoy);
                refuse(parse(drift), "source drift: " + path);
            }
        }
    }

    @Test void duplicateAndNonJavaTargetsRefuse() throws Exception {
        var baseline = before();
        var inputs = parse(baseline);
        for (SourceFile input : inputs) {
            var duplicate = new ArrayList<>(inputs);
            duplicate.add(input);
            refuse(duplicate, "duplicate target: " + input.getSourcePath());
            var nonJava = new ArrayList<>(inputs);
            nonJava.remove(input);
            nonJava.add(PlainText.builder().sourcePath(input.getSourcePath()).text(input.printAll()).build());
            refuse(nonJava, "target is not a Java compilation unit: " + input.getSourcePath());
        }
    }

    @Test void attributedTreesMetadataAndUnrelatedInputRemainSound() throws Exception {
        var inputs = new ArrayList<>(parse(before()));
        var unrelated = PlainText.builder().sourcePath(Path.of("docs/unrelated.md"))
                .text("```java\nvoid invalidate() { cache = null; }\n```\n").build();
        inputs.add(unrelated);
        var changes = results(inputs);
        assertEquals(2, changes.size());
        AtomicInteger resolvedInvalidateCalls = new AtomicInteger();
        for (Result change : changes) {
            SourceFile original = Objects.requireNonNull(change.getBefore());
            J.CompilationUnit after = assertInstanceOf(J.CompilationUnit.class, change.getAfter());
            assertEquals(original.getSourcePath(), after.getSourcePath());
            assertEquals(original.getId(), after.getId());
            assertEquals(original.getMarkers(), after.getMarkers().removeByType(RecipesThatMadeChanges.class));
            var lineage = after.getMarkers().findAll(RecipesThatMadeChanges.class);
            assertEquals(1, lineage.size(), "only the real scheduler lineage marker is added");
            assertEquals(1, lineage.getFirst().getRecipes().size());
            var sequence = lineage.getFirst().getRecipes().iterator().next();
            assertTrue(sequence.stream().anyMatch(recipe -> recipe.getName().equals(NAME)));
            var leaf = assertInstanceOf(M3HashPinnedJavaSnapshotRecipe.class, sequence.getLast());
            assertEquals(ID, leaf.getCrateName());
            assertEquals(original.getCharset(), after.getCharset());
            assertEquals(original.isCharsetBomMarked(), after.isCharsetBomMarked());
            assertEquals(original.getFileAttributes(), after.getFileAttributes());
            assertEquals(AFTER.get(after.getSourcePath().toString()), sha(after.printAll()));
            String simple = after.getSourcePath().getFileName().toString().replace(".java", "");
            assertEquals("com.m3.collections." + simple,
                    Objects.requireNonNull(after.getClasses().getFirst().getType()).getFullyQualifiedName());
            new JavaIsoVisitor<AtomicInteger>() {
                @Override public J.MethodInvocation visitMethodInvocation(J.MethodInvocation method, AtomicInteger count) {
                    J.MethodInvocation result = super.visitMethodInvocation(method, count);
                    if (result.getSimpleName().equals("invalidate")) {
                        var type = Objects.requireNonNull(result.getMethodType(), "attributed invalidation call");
                        assertTrue(type.getDeclaringType().getFullyQualifiedName().contains(
                                "M3LongBitmapFilteredSnapshot"));
                        count.incrementAndGet();
                    }
                    return result;
                }
            }.visit(after, resolvedInvalidateCalls);
        }
        assertEquals(6, resolvedInvalidateCalls.get(), "all six frozen invalidation call sites are attributed");
        assertEquals("```java\nvoid invalidate() { cache = null; }\n```\n", unrelated.printAll());
        assertEquals(AFTER.keySet(), output(inputs).keySet());
    }
