     * No predicate is evaluated and no value payload is copied.
     */
    public M3LongBitmapFilteredSnapshot slice(int offset, int length) {
        M3LongIndexProjection range = selected.slice(offset, length);
        if (offset == 0 && length == size()) return this;
        BitSet rangeBits = new BitSet();
        for (int i = 0; i < range.size(); i++) rangeBits.set(range.physicalIndex(i));
        return new M3LongBitmapFilteredSnapshot(range, rangeBits);
    }

    /** Original canonical physical row, not the logical ordinal in this view. */
    public int physicalIndex(int ordinal) { return selected.physicalIndex(ordinal); }

    /** O(1) positional select, including repeated equal-valued occurrences. */
    public long get(int ordinal) { return selected.get(ordinal); }

    /** O(1) bitmap membership for this particular snapshot's physical slots. */
    public boolean includesPhysicalIndex(int physicalIndex) {
        return physicalIndex >= 0 && physicalMask.get(physicalIndex);
    }

    /** The original bitmap cannot be mutated through the returned diagnostic copy. */
    public BitSet physicalMaskCopy() { return (BitSet) physicalMask.clone(); }

    @Override public int size() { return selected.size(); }

    @Override public boolean contains(long value) {
        M3LongIndexProjection.Order order = selected.order();
        if (order != M3LongIndexProjection.Order.ENCOUNTER) {
            return containsSorted(value, order == M3LongIndexProjection.Order.DESCENDING);
        }
        for (int i = 0; i < size(); i++) if (selected.get(i) == value) return true;
        return false;
    }

    /** Reuses the immutable projection order without callbacks or another index. */
    private boolean containsSorted(long value, boolean descending) {
        int low = 0;
        int high = size();
        while (low < high) {
            int middle = low + ((high - low) >>> 1);
            long candidate = selected.get(middle);
            if (candidate == value) return true;
            if (descending ? candidate > value : candidate < value) low = middle + 1;
            else high = middle;
        }
        return false;
    }

    @Override public long[] toArray() { return selected.toArray(); }

    @Override public void clear() {
        throw new UnsupportedOperationException("immutable bitmap filtered snapshot");
    }

    @Override public M3LongIterator iterator() {
        return new M3LongIterator() {
            private int cursor;
            @Override public boolean hasNext() { return cursor < size(); }
            @Override public long nextLong() {
                if (!hasNext()) throw new NoSuchElementException();
                return selected.get(cursor++);
            }
        };
    }

    /** SIZED, immutable, ordinal-splittable primitive traversal; never tests predicates. */
    @Override public Spliterator.OfLong longSpliterator() {
        return new IndexSpliterator(0, size());
    }

    private final class IndexSpliterator implements Spliterator.OfLong {
        private int cursor;
        private final int fence;
        IndexSpliterator(int cursor, int fence) { this.cursor = cursor; this.fence = fence; }
        @Override public boolean tryAdvance(LongConsumer consumer) {
            Objects.requireNonNull(consumer, "consumer");
            if (cursor >= fence) return false;
            consumer.accept(selected.get(cursor++));
            return true;
        }
        @Override public OfLong trySplit() {
            int middle = cursor + ((fence - cursor) >>> 1);
            if (middle == cursor) return null;
            IndexSpliterator prefix = new IndexSpliterator(cursor, middle);
            cursor = middle;
            return prefix;
        }
        @Override public long estimateSize() { return fence - cursor; }
        @Override public int characteristics() {
            return ORDERED | NONNULL | SIZED | SUBSIZED | IMMUTABLE;
        }
    }

    /**
     * Opt-in epoch-controlled filtered wrapper. It evaluates a predicate at most
     * once per admitted source occurrence per revision; repeated reads of an
     * unchanged epoch reuse the same immutable bitmap snapshot. The supplied
     * revision MUST cover source changes and predicate dependencies. The source
     * must not mutate without advancing the revision; mutable predicates without
     * revision signals are not supported. Changing revision during capture fails
     * rather than publishing an invalid cache. No automatic JDK live-view claim.
     */
    public static final class VersionedView implements M3LongCollection {
        private final M3LongCollection source;
        private final LongPredicate predicate;
        private final LongSupplier revision;
        private volatile Cache cache;
        // Guarded by this monitor. Equality spans one capture; wrapping would
        // require 2^64 synchronous invalidations during that single capture.
        private long invalidationGeneration;

        private static final class Cache {
            final long revision;
            final M3LongBitmapFilteredSnapshot bitmap;
            volatile M3LongBitmapFilteredSnapshot ascending;
            volatile M3LongBitmapFilteredSnapshot descending;
            Cache(long revision, M3LongBitmapFilteredSnapshot bitmap) {
                this.revision = revision;
                this.bitmap = bitmap;
            }
        }

        public VersionedView(M3LongCollection source, LongPredicate predicate,
                             LongSupplier revision) {
            this.source = Objects.requireNonNull(source, "source");
            this.predicate = Objects.requireNonNull(predicate, "predicate");
            this.revision = Objects.requireNonNull(revision, "revision");
        }

        /** Invalidate manually when the owner cannot publish a trustworthy epoch. */
        public synchronized void invalidate() {
            invalidationGeneration++;
            cache = null;
        }

        private Cache current() {
            long stamp = revision.getAsLong();
            Cache seen = cache;
            if (seen != null && seen.revision == stamp) return seen;
            synchronized (this) {
                // Revision suppliers and predicates can invalidate reentrantly.
                // Capture before either callback so publication cannot erase it.
                long generation = invalidationGeneration;
                stamp = revision.getAsLong();
                seen = cache;
                if (seen != null && seen.revision == stamp) return seen;
                long[] detached = source.toArray();
                M3LongBitmapFilteredSnapshot fresh = M3LongBitmapFilteredSnapshot.snapshot(detached, predicate);
                if (revision.getAsLong() != stamp) {
                    throw new ConcurrentModificationException("revision changed during bitmap capture");
                }
                Cache rebuilt = new Cache(stamp, fresh);
                // Return this call's detached result without retrying callbacks.
                // A reentrant invalidation reserves rebuilding for the next read.
                if (invalidationGeneration == generation) cache = rebuilt;
                return rebuilt;
            }
        }

        private void requireUnchanged(Cache owner) {
            if (revision.getAsLong() != owner.revision) {
                throw new ConcurrentModificationException("filtered view revision changed");
            }
        }

        /** Captured immutable filtered image of the currently published revision. */
        public M3LongBitmapFilteredSnapshot snapshot() { return current().bitmap; }

        /** Memoized sorted wrapper for a stable revision; no predicate re-execution. */
        public M3LongBitmapFilteredSnapshot sortedAscending() {
            Cache c = current();
            M3LongBitmapFilteredSnapshot result = c.ascending;
            if (result == null) synchronized (c) {
                result = c.ascending;
                if (result == null) c.ascending = result = c.bitmap.sortedAscending();
            }
            requireUnchanged(c);
            return result;
        }

        public M3LongBitmapFilteredSnapshot sortedDescending() {
            Cache c = current();
            M3LongBitmapFilteredSnapshot result = c.descending;
            if (result == null) synchronized (c) {
                result = c.descending;
                if (result == null) c.descending = result = c.bitmap.sortedDescending();
            }
            requireUnchanged(c);
            return result;
        }

        @Override public int size() { return current().bitmap.size(); }
        @Override public boolean contains(long value) { return current().bitmap.contains(value); }
        @Override public long[] toArray() { return current().bitmap.toArray(); }
        @Override public void clear() {
            throw new UnsupportedOperationException("read-only epoch filtered view");
        }
        @Override public M3LongIterator iterator() {
            Cache owner = current();
            M3LongIterator delegate = owner.bitmap.iterator();
            return new M3LongIterator() {
                @Override public boolean hasNext() {
                    requireUnchanged(owner);
                    return delegate.hasNext();
                }
                @Override public long nextLong() {
                    requireUnchanged(owner);
                    return delegate.nextLong();
                }
            };
        }
        // The inherited unsplittable primitive stream uses the epoch-checked iterator.
    }
}

